async function insertar(lote, numero, base) {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/ventas`, {
    method: "POST",
    headers: {
      "apikey":        ANON_KEY,
      "Authorization": `Bearer ${ANON_KEY}`,
      "Content-Type":  "application/json",
      "Prefer":        "return=minimal"
    },
    body: JSON.stringify(lote)
  });

  if (res.ok) {
    console.log(`✅ Lote ${numero}: ${3050 + base + lote.length}/4288 ventas cargadas`);
  } else {
    const txt = await res.text();
    console.error(`❌ Lote ${numero} falló (${res.status}): ${txt.slice(0, 200)}`);
  }
}

async function main() {
  console.log(`Retomando carga desde venta 3051... faltan ${ventas.length} ventas.`);

  const ahora = Date.now();
  const payload = ventas.map(function(v, i) {
    const { id, ...resto } = v;
    return { id: ahora + i, ...resto };
  });

  let numero = 1;
  for (let i = 0; i < payload.length; i += LOTE) {
    const lote = payload.slice(i, i + LOTE);
    await insertar(lote, numero++, i);
    await new Promise(r => setTimeout(r, 300));
  }

  console.log("\n🎉 Carga finalizada. Podés borrar este archivo del repo.");
}

